  const STOP_WORDS = new Set([
    'what', 'is', 'are', 'the', 'a', 'an', 'and', 'or', 'in', 'on', 'of', 'to', 'for', 'with',
    'by', 'at', 'from', 'as', 'how', 'why', 'which', 'where', 'who', 'when', 'does', 'do',
    'can', 'you', 'tell', 'me', 'about', 'describe', 'explain', 'give', 'some', 'any', 'that',
    'this', 'these', 'those', 'have', 'has', 'had', 'will', 'would', 'could', 'should', 'not'
  ]);

  function normalizeText(text) {
    return (text || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
  }

  function extractTokens(text) {
    const norm = normalizeText(text);
    return norm.split(' ').filter(w => w.length >= 3 && !STOP_WORDS.has(w));
  }

  /**
   * High-accuracy matcher across the QA dataset
   */
  function findBestMatch(userQuery) {
    if (!userQuery || !userQuery.trim()) return null;
    const cleanQuery = normalizeText(userQuery);
    const tokens = extractTokens(userQuery);

    // 1. Exact or near-exact question match (highest priority)
    for (let i = 0; i < QA_LIST.length; i++) {
      const qNorm = normalizeText(QA_LIST[i].question);
      if (qNorm === cleanQuery || cleanQuery === qNorm) {
        return { ...QA_LIST[i], matchType: 'exact', score: 100 };
      }
      // Substring match
      if (cleanQuery.length > 10 && (qNorm.includes(cleanQuery) || cleanQuery.includes(qNorm))) {
        return { ...QA_LIST[i], matchType: 'substring', score: 90 };
      }
    }

    // 2. Inverted index keyword scoring
    const scores = new Map();
    tokens.forEach(tok => {
      const matches = INVERTED_INDEX[tok] || [];
      matches.forEach(idx => {
        scores.set(idx, (scores.get(idx) || 0) + 10);
      });
      // Prefix matching
      if (tok.length >= 4) {
        Object.keys(INVERTED_INDEX).forEach(k => {
          if (k !== tok && (k.startsWith(tok) || tok.startsWith(k))) {
            (INVERTED_INDEX[k] || []).forEach(idx => {
              scores.set(idx, (scores.get(idx) || 0) + 4);
            });
          }
        });
      }
    });

    // Boost score if question words match consecutively
    for (let [idx, score] of scores.entries()) {
      const entry = QA_LIST[idx];
      const qNorm = normalizeText(entry.question);
      let consecutiveMatches = 0;
      for (let i = 0; i < tokens.length - 1; i++) {
        if (qNorm.includes(tokens[i] + ' ' + tokens[i+1])) {
          consecutiveMatches += 15;
        }
      }
      scores.set(idx, score + consecutiveMatches);
    }

    // Find highest score
    let bestIdx = -1;
    let maxScore = 0;
    for (let [idx, score] of scores.entries()) {
      if (score > maxScore) {
        maxScore = score;
        bestIdx = idx;
      }
    }

    if (bestIdx >= 0 && maxScore >= 10) {
      return { ...QA_LIST[bestIdx], matchType: 'keyword', score: maxScore };
    }

    return null;
  }

  root.CryoverseQA = {
    questions: QA_LIST,
    index: INVERTED_INDEX,
    indianStations: INDIAN_STATIONS,
    themes: RESEARCH_THEMES,
    findBestMatch: findBestMatch,
    extractTokens: extractTokens,
    normalizeText: normalizeText
  };

